function applyLanguage(code){if(!LANGS[code])code="en";currentLang=code;localStorage.setItem("gee2026-lang",code);document.documentElement.lang=code;document.documentElement.dir=code==="ar"?"rtl":"ltr";document.getElementById("lang").value=code;document.querySelectorAll("[data-i18n]").forEach(e=>e.textContent=tr(e.dataset.i18n));document.querySelectorAll("[data-i18n-placeholder]").forEach(e=>e.placeholder=tr(e.dataset.i18nPlaceholder));document.title=currentLang==="ar"?"فعالية الخطوبة العالمية 2026":"Global Engagement Event 2026";const md=document.getElementById("metaDescription");if(md)md.content=currentLang==="ar"?"فعالية دولية خاصة للنساء الباحثات عن الزواج والأسرة والاستقرار ومستقبل جاد.":"A private international event for women seeking marriage, family, stability and a serious future.";if(document.getElementById("languagesSpoken"))fillWorldLanguages(document.getElementById("languageSearch")?.value||"");}
