function cairoDeadlineMs(){const target={year:2026,month:11,day:30,hour:23,minute:59,second:59};let guess=Date.UTC(2026,10,30,23,59,59);const fmt=new Intl.DateTimeFormat("en-CA",{timeZone:EVENT_TIMEZONE,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hourCycle:"h23"});for(let i=0;i<4;i++){const p=Object.fromEntries(fmt.formatToParts(new Date(guess)).filter(x=>x.type!=="literal").map(x=>[x.type,+x.value]));const shown=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second);const wanted=Date.UTC(target.year,target.month-1,target.day,target.hour,target.minute,target.second);guess+=wanted-shown;}return guess;}
function tick(){let x=cairoDeadlineMs()-Date.now();if(x<0)x=0;const v=[Math.floor(x/86400000),Math.floor(x/3600000)%24,Math.floor(x/60000)%60,Math.floor(x/1000)%60];["days","hours","minutes","seconds"].forEach((id,i)=>document.getElementById(id).textContent=String(v[i]).padStart(2,"0"));}
