function spokenLabel(x){if(currentLang!=="ar")return x;if(x==="Chinese (Mandarin)")return "الصينية (الماندرين)";if(x==="Cantonese")return "الكانتونية";return AR_LANGUAGE_NAMES[x]||x}
function fillWorldLanguages(filter=""){const s=document.getElementById("languagesSpoken");if(!s)return;const chosen=new Set([...s.selectedOptions].map(o=>o.value));const f=filter.toLowerCase();s.innerHTML="";WORLD_LANGUAGES.filter(x=>x.toLowerCase().includes(f)||spokenLabel(x).toLowerCase().includes(f)).forEach(x=>{const o=new Option(spokenLabel(x),x);o.selected=chosen.has(x);s.add(o)});}
function syncDress(){const muslim=document.getElementById("religion").value==="Muslim",wrap=document.getElementById("dressWrap"),d=document.getElementById("religiousDress");wrap.classList.toggle("d-none",!muslim);if(muslim)d.name="religiousDress";else{d.value="";d.removeAttribute("name")}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
async function send(data) {
  if (!API_URL) {
    throw new Error(currentLang === "ar" ? "خدمة التسجيل غير متصلة حاليًا." : "The registration service is not connected.");
  }

  const response = await fetch(API_URL, {
    method: "POST",
    redirect: "follow",
    body: JSON.stringify(data)
  });

  if (!response.ok) {
    throw new Error(currentLang === "ar" ? "تعذر الاتصال بخدمة التسجيل." : "Could not connect to the registration service.");
  }

  const result = await response.json();

  if (result.result !== "success") {
    throw new Error(result.message || result.error || (currentLang === "ar" ? "تعذر إكمال التسجيل." : "Registration failed."));
  }

  if (!result.registrationId) {
    throw new Error(currentLang === "ar" ? "تم الاتصال بالخادم ولكن لم يتم إنشاء رقم تسجيل." : "The server responded but did not return a registration ID.");
  }

  return result;
}
document.addEventListener("DOMContentLoaded",()=>{initLang();fillWorldLanguages();document.getElementById("languageSearch").addEventListener("input",e=>fillWorldLanguages(e.target.value));document.getElementById("religion").addEventListener("change",syncDress);syncDress();iti=window.intlTelInput(document.getElementById("phone"),{initialCountry:"eg",separateDialCode:true,strictMode:true,loadUtils:()=>import("https://cdn.jsdelivr.net/npm/intl-tel-input@25.12.5/build/js/utils.js")});document.getElementById("gender").addEventListener("change",e=>{const male=e.target.value==="Male";document.getElementById("submitBtn").disabled=male;if(male)bootstrap.Modal.getOrCreateInstance(document.getElementById("femaleModal")).show()});document.getElementById("registrationForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;f.classList.add("was-validated");if(document.getElementById("gender").value!=="Female"){if(document.getElementById("gender").value==="Male")bootstrap.Modal.getOrCreateInstance(document.getElementById("femaleModal")).show();return}if(Number(document.getElementById("age").value)<18)return;if(iti&&!iti.isValidNumber()){document.getElementById("phone").setCustomValidity("invalid")}else document.getElementById("phone").setCustomValidity("");if(!f.checkValidity())return;const fd=new FormData(f),data=Object.fromEntries(fd.entries());data.languages=[...document.getElementById("languagesSpoken").selectedOptions].map(o=>o.value);data.phone=iti.getNumber();data.registrationLanguage=currentLang;data.consent=document.getElementById("consent").checked;if(data.religion!=="Muslim")delete data.religiousDress;const btn=document.getElementById("submitBtn");btn.disabled=true;try{const out=await send(data);if(out.demo)return;document.getElementById("regId").textContent=out.registrationId;document.getElementById("summary").innerHTML=`<b>${escapeHtml(data.fullName)}</b><br>${escapeHtml(data.preferredLocation)}<br>${escapeHtml(data.email)}`;bootstrap.Modal.getOrCreateInstance(document.getElementById("successModal")).show();f.reset();iti.setNumber("");syncDress();f.classList.remove("was-validated")}catch(err){document.getElementById("formStatus").innerHTML=`<div class="alert alert-danger mt-3">${escapeHtml(err.message)}</div>`}finally{btn.disabled=false}});const obs=new IntersectionObserver(es=>es.forEach(x=>x.isIntersecting&&x.target.classList.add("visible")),{threshold:.1});document.querySelectorAll(".reveal").forEach(x=>obs.observe(x));tick();setInterval(tick,1000);});
